import { describe, expect, test } from "bun:test";
import NotInstalledTargetsModel from "./not-installed-targets-model.js";

describe("groupByRepo", () => {
  const appTrails = (id: string) => ({
    id,
    repo: "git@github.com:example-org/app-trails.git",
    shortName: "example-org/app-trails",
    cloneCommand: "git clone git@github.com:example-org/app-trails.git && cd app-trails",
    url: "https://github.com/example-org/app-trails",
    description: "App and App Lite",
  });

  test("entries sharing a repo collapse into one row carrying every target", () => {
    const groups = NotInstalledTargetsModel.groupByRepo([
      appTrails("myapp"),
      appTrails("myappLite"),
      {
        id: "otherapp",
        repo: "git@github.com:example-org/other-trails.git",
        shortName: "example-org/other-trails",
        cloneCommand: "git clone git@github.com:example-org/other-trails.git && cd other-trails",
      },
    ]);

    expect(groups.map((g) => g.shortName)).toEqual(["example-org/app-trails", "example-org/other-trails"]);
    expect(groups[0].targets).toEqual(["myapp", "myappLite"]);
    expect(groups[0].url).toBe("https://github.com/example-org/app-trails");
    expect(groups[0].description).toBe("App and App Lite");
    expect(groups[1].targets).toEqual(["otherapp"]);
    expect(groups[1].url).toBeNull();
  });

  test("a repeated target id renders once per repo", () => {
    const groups = NotInstalledTargetsModel.groupByRepo([appTrails("myapp"), appTrails("myapp")]);
    expect(groups).toHaveLength(1);
    expect(groups[0].targets).toEqual(["myapp"]);
  });

  test("one repo spelled via SSH and HTTPS across registry files renders as one row", () => {
    const groups = NotInstalledTargetsModel.groupByRepo([
      appTrails("myapp"),
      { ...appTrails("myappLite"), repo: "https://github.com/example-org/app-trails" },
    ]);
    expect(groups).toHaveLength(1);
    expect(groups[0].targets).toEqual(["myapp", "myappLite"]);
    expect(groups[0].repo).toBe("git@github.com:example-org/app-trails.git");
  });

  test("entries missing a repo or id are dropped rather than rendered blank", () => {
    const groups = NotInstalledTargetsModel.groupByRepo([
      { id: "", repo: "git@github.com:example-org/app-trails.git" },
      { id: "ok", repo: "" },
      null,
    ]);
    expect(groups).toEqual([]);
  });

  test("no entries means no section", () => {
    expect(NotInstalledTargetsModel.groupByRepo([])).toEqual([]);
    expect(NotInstalledTargetsModel.groupByRepo(undefined)).toEqual([]);
  });

  test("a non-http(s) url never reaches an href", () => {
    const hostile = NotInstalledTargetsModel.groupByRepo([{ ...appTrails("myapp"), url: "javascript:alert(1)" }]);
    expect(hostile[0].url).toBeNull();
    expect(NotInstalledTargetsModel.safeHttpUrl("https://github.com/example-org/app-trails")).toBe(
      "https://github.com/example-org/app-trails",
    );
    expect(NotInstalledTargetsModel.safeHttpUrl("data:text/html,x")).toBeNull();
    expect(NotInstalledTargetsModel.safeHttpUrl(null)).toBeNull();
  });
});

import java.io.File
import java.nio.file.Files
import kotlin.test.AfterTest
import kotlin.test.Test
import kotlin.test.assertFalse
import kotlin.test.assertTrue

/**
 * Unit tests for [shouldReinstallSdkNodeModules] — the pure skip-vs-reinstall decision behind
 * `ensureSdkNodeModules`. Exercised with on-disk fixtures only (no bun, no Gradle), so the
 * lockfile-fingerprint contract is guarded directly: the load-bearing property is that a `bun.lock`
 * change forces a reinstall (rather than bundling against stale deps from a warm `node_modules`).
 */
class ShouldReinstallSdkNodeModulesTest {

  private val sdkDir: File = Files.createTempDirectory("sdk-reinstall-test").toFile()

  @AfterTest
  fun cleanup() {
    sdkDir.deleteRecursively()
  }

  private fun writeBinaries(dts: Boolean = true, esbuild: Boolean = true) {
    File(sdkDir, "node_modules/.bin").mkdirs()
    if (dts) File(sdkDir, "node_modules/.bin/dts-bundle-generator").writeText("#!/usr/bin/env node\n")
    if (esbuild) File(sdkDir, "node_modules/.bin/esbuild").writeText("native-binary\n")
  }

  private fun writeLock(text: String) = File(sdkDir, "bun.lock").writeText(text)

  private fun writeStamp(text: String) {
    File(sdkDir, "node_modules").mkdirs()
    File(sdkDir, "node_modules/.trailblaze-install-lock").writeText(text)
  }

  @Test
  fun `reinstall when node_modules is absent`() {
    writeLock("lock-v1")
    assertTrue(shouldReinstallSdkNodeModules(sdkDir))
  }

  @Test
  fun `skip when both binaries present and stamp matches the current lock`() {
    writeLock("lock-v1")
    writeBinaries()
    writeStamp("lock-v1")
    assertFalse(shouldReinstallSdkNodeModules(sdkDir))
  }

  @Test
  fun `reinstall when the lockfile changed since the recorded stamp`() {
    // The load-bearing case: a warm node_modules whose bun.lock has since changed.
    writeLock("lock-v2")
    writeBinaries()
    writeStamp("lock-v1")
    assertTrue(shouldReinstallSdkNodeModules(sdkDir))
  }

  @Test
  fun `reinstall when binaries present but no stamp recorded`() {
    writeLock("lock-v1")
    writeBinaries()
    assertTrue(shouldReinstallSdkNodeModules(sdkDir))
  }

  @Test
  fun `reinstall when a required binary is missing even though the stamp matches`() {
    writeLock("lock-v1")
    writeStamp("lock-v1")
    writeBinaries(dts = false, esbuild = true)
    assertTrue(shouldReinstallSdkNodeModules(sdkDir))
  }

  @Test
  fun `skip when bun_lock is absent and the stamp records the empty fingerprint`() {
    // No bun.lock => fingerprint is "" ; a prior install that recorded "" is still a match.
    writeBinaries()
    writeStamp("")
    assertFalse(shouldReinstallSdkNodeModules(sdkDir))
  }
}

package xyz.block.trailblaze.android.test.tools

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.semantics.SemanticsActions
import androidx.compose.ui.semantics.SemanticsNode
import androidx.compose.ui.semantics.SemanticsProperties
import androidx.compose.ui.semantics.SemanticsPropertyKey
import androidx.compose.ui.semantics.getOrNull
import androidx.compose.ui.test.SemanticsMatcher
import androidx.compose.ui.test.SemanticsNodeInteraction
import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.click
import androidx.compose.ui.test.junit4.AndroidComposeTestRule
import androidx.compose.ui.test.longClick
import androidx.compose.ui.test.performClick
import androidx.compose.ui.test.performScrollTo
import androidx.compose.ui.test.performSemanticsAction
import androidx.compose.ui.test.performTextReplacement
import androidx.compose.ui.test.performTouchInput
import xyz.block.trailblaze.android.test.AndroidTestTarget

/**
 * Acts on a Compose semantics node that has already been chosen, by identity.
 *
 * The app's own Compose rule is asked for the node whose `SemanticsNode.id` matches — not for a node
 * matching a test tag or some text. The selector already picked a node out of the captured tree;
 * asking Compose to find "the node with this test tag" would be a second, differently-specified
 * search, and `hasText` alone routinely matches several nodes.
 *
 * Reads are against the **unmerged** tree throughout, matching what the hierarchy collector
 * captured. Unmerged nodes are finer-grained than a user thinks of them — a Button's label Text is
 * its own node and carries no click action — so [nearestWith] moves the action to the node that
 * owns it.
 */
internal object AndroidComposeActions {

  /**
   * Taps the node with a touch, at the point on it a touch actually reaches.
   *
   * A touch, not the `OnClick` semantics action, because on this app the action is not equivalent
   * to it. Square's Market rows publish `OnClick` and act only on real pointer input, so
   * dispatching the action to one succeeds, changes nothing, and leaves the trail believing it has
   * navigated — two trails each spent their remaining steps on a More menu they thought they had
   * left. It also matches the app build these recordings were made under: it gave that same
   * Settings row a `GESTURE`, not an `ACTION_CLICK`.
   *
   * The POINT is what moves instead. `performClick` taps the center, which goes wherever the hit
   * test sends it — through an overlay drawn later, onto that overlay — while this tool still
   * reports success because its selector matched. Both drivers scroll the More menu until Settings
   * is on screen and tap it; the recording driver's scroll overshot to 400px clear of the
   * promotional banner and this one stops with the row 10px inside it. [reachablePoint] takes the
   * nearest point on the row the touch still reaches, which is the same tap on the same row.
   *
   * Only a node with no reachable point at all — covered everywhere, so no touch can express the
   * tap — falls back to the action, and says so in its result.
   */
  suspend fun click(target: AndroidTestTarget, semanticsId: Int): String? {
    val rule = target.requireComposeRule()
    val (site, relocation) = target.nearestWith(semanticsId, "clickable", SemanticsActions.OnClick)
    val node = target.findSemanticsNode(site)
    val point = node?.let { target.reachablePoint(it) }
    val moved = point != null && point != node.boundsInWindow.center
    target.dispatchAndAwaitSettle {
      when {
        point != null ->
          rule.nodeWithId(site).performTouchInput { click(point - node.boundsInWindow.topLeft) }
        node != null && node.offersClickAction() ->
          rule.nodeWithId(site).performSemanticsAction(SemanticsActions.OnClick)
        else -> rule.nodeWithId(site).performClick()
      }
    }
    return listOfNotNull(
      relocation,
      RELOCATED_TAP_NOTE.takeIf { moved },
      COVERED_NOTE.takeIf { node != null && point == null },
    ).takeIf { it.isNotEmpty() }?.joinToString(" ")
  }

  /** Whether dispatching the click action to this node would reach a handler at all. */
  private fun SemanticsNode.offersClickAction(): Boolean {
    if (!config.contains(SemanticsActions.OnClick)) return false
    if (config.contains(SemanticsProperties.Disabled)) return false
    // The editable exclusion is the gate's: `ACTION_CLICK` focuses a field without honoring the
    // touch offset, so it cannot place a caret where the recording put one.
    return !config.contains(SemanticsActions.SetText)
  }

  /**
   * Whether a touch at [point] would be delivered to [node] (or something inside it).
   *
   * Answered by finding the last node in draw order whose bounds contain that point: Compose draws
   * siblings in composition order, so the deepest-last node containing a point is the one its hit
   * test hands the touch to.
   */
  private fun touchAtReaches(roots: List<SemanticsNode>, node: SemanticsNode, point: Offset): Boolean {
    var topMost: SemanticsNode? = null
    fun visit(current: SemanticsNode) {
      if (current.boundsInWindow.contains(point)) topMost = current
      current.children.forEach(::visit)
    }
    roots.forEach(::visit)
    val hit = topMost ?: return true
    return generateSequence(hit) { it.parent }.any { it.id == node.id }
  }

  /**
   * The point inside [node] a touch should be sent to: its center, or — when something is drawn
   * over the center — the nearest point on the node the hit test still delivers to it.
   *
   * Scans the node's own box, nearest-to-center first, and takes the first point that reaches it.
   * Null means the node is covered everywhere and no touch can reach it.
   *
   * The roots are read ONCE for the whole scan. Every probe answers a question about one tree, so
   * re-reading per probe is not more accurate — and `composeRoots()` synchronizes with the app,
   * which on a never-idle screen means paying the framework's idle timeout before falling back.
   * A covered center puts 64 probes behind that, so this is the difference between one timeout and
   * sixty-five.
   */
  private fun AndroidTestTarget.reachablePoint(node: SemanticsNode): Offset? {
    val roots = composeRoots()
    val box = node.boundsInWindow
    val center = box.center
    if (touchAtReaches(roots, node, center)) return center
    // An inset keeps every candidate off the node's own boundary, where the hit test is ambiguous
    // and a rounding difference decides the winner.
    val stepsX = 8
    val stepsY = 8
    val insetX = box.width / (stepsX * 2)
    val insetY = box.height / (stepsY * 2)
    return (0 until stepsX * stepsY)
      .map { i ->
        Offset(
          box.left + insetX + (box.width - 2 * insetX) * (i % stepsX) / (stepsX - 1f),
          box.top + insetY + (box.height - 2 * insetY) * (i / stepsX) / (stepsY - 1f),
        )
      }
      .sortedBy { (it - center).getDistanceSquared() }
      .firstOrNull { touchAtReaches(roots, node, it) }
  }

  private const val RELOCATED_TAP_NOTE =
    "Another element was drawn over this one's center, so the tap was moved to the nearest point " +
      "on it the touch still reaches."

  private const val COVERED_NOTE =
    "Another element was drawn over this one, so the click action was dispatched to it directly " +
      "rather than as a touch that would have landed on the overlay."

  /**
   * A press held past the long-press timeout, dispatched at the resolved node itself.
   *
   * Deliberately NOT routed through [act]: a long press is a raw gesture on the driver these
   * recordings were made under — a touch down at the element's center, held — and the node that
   * reacts to it is decided by Compose's own hit test, exactly as it would be for a finger. Moving
   * the gesture to an ancestor carrying `OnLongClick` would send it somewhere the recording never
   * touched, and the case this exists for (a trail long-pressing an EMPTY favorites tile) has no
   * such ancestor to move to.
   */
  suspend fun longClick(target: AndroidTestTarget, semanticsId: Int) {
    val rule = target.requireComposeRule()
    target.dispatchAndAwaitSettle { rule.nodeWithId(semanticsId).performTouchInput { longClick() } }
  }

  suspend fun replaceText(target: AndroidTestTarget, semanticsId: Int, value: String): String? =
    act(target, semanticsId, "a text input", SemanticsActions.SetText) {
      it.performTextReplacement(value)
    }

  /**
   * Scrolls this node's own scrollable ancestor until the node is in view.
   *
   * Preferred over scrolling whichever container looks like the main one whenever the node is
   * already in the tree: on a screen with an overlay, both the overlay's list and the screen
   * underneath it are attached and scrollable, and only the node itself knows which one it rides.
   */
  suspend fun scrollTo(target: AndroidTestTarget, semanticsId: Int) {
    target.dispatchAndAwaitSettle {
      target.requireComposeRule().nodeWithId(semanticsId).performScrollTo()
    }
  }

  fun assertDisplayed(target: AndroidTestTarget, semanticsId: Int) {
    target.requireComposeRule().nodeWithId(semanticsId).assertExists().assertIsDisplayed()
  }

  private suspend fun act(
    target: AndroidTestTarget,
    semanticsId: Int,
    capability: String,
    action: SemanticsPropertyKey<*>,
    perform: (SemanticsNodeInteraction) -> Unit,
  ): String? {
    val rule = target.requireComposeRule()
    val (site, relocation) = target.nearestWith(semanticsId, capability, action)
    target.dispatchAndAwaitSettle { perform(rule.nodeWithId(site)) }
    return relocation
  }

  /**
   * Finds the semantics node that can actually take the action, starting from the one the selector
   * resolved: self, then ancestors, then descendants.
   *
   * Both directions are ordinary Compose structure. Ascending covers the label inside a `Button`;
   * descending covers a `TextField` whose test tag sits on the wrapper while the set-text action
   * lives on the inner text node. The relocation is returned so the tool reports it — a silent jump
   * to a neighbouring node is how a test ends up clicking something nobody asked for.
   *
   * Descending stops at the shallowest depth that has any candidate and fails when that depth has
   * more than one, for the same reason [AndroidViewActions] does: the resolver refuses an ambiguous
   * selector, and taking the first of several equally close descendants would reinstate that guess.
   */
  private fun AndroidTestTarget.nearestWith(
    semanticsId: Int,
    capability: String,
    action: SemanticsPropertyKey<*>,
  ): Pair<Int, String?> {
    val resolved =
      findSemanticsNode(semanticsId)
        ?: error(
          "Compose node $semanticsId is no longer in the semantics tree; the screen changed " +
            "between observation and action.",
        )
    if (resolved.config.contains(action)) return semanticsId to null

    var ancestor = resolved.parent
    while (ancestor != null) {
      if (ancestor.config.contains(action)) {
        return ancestor.id to resolved.relocationNote(capability, "ancestor", ancestor)
      }
      ancestor = ancestor.parent
    }

    val nearest = resolved.shallowestDescendantsWith { it.config.contains(action) }
    return when (nearest.size) {
      // Nothing in the chain owns the action. Act on the resolved node and let Compose's own error
      // name the missing action rather than paraphrasing it here.
      0 -> semanticsId to null
      1 -> nearest[0].id to resolved.relocationNote(capability, "descendant", nearest[0])
      else -> error(
        "Compose node $semanticsId is not $capability and ${nearest.size} of its descendants " +
          "are, all equally close: ${nearest.joinToString { it.id.toString() }}. Refusing to " +
          "pick one — narrow the selector to the node the action should land on.",
      )
    }
  }

  /**
   * Every descendant satisfying [predicate] at the shallowest depth where any does, so a capable
   * child that itself contains a capable grandchild still resolves to the child.
   */
  private fun SemanticsNode.shallowestDescendantsWith(
    predicate: (SemanticsNode) -> Boolean,
  ): List<SemanticsNode> {
    var level = children
    while (level.isNotEmpty()) {
      level.filter(predicate).takeIf { it.isNotEmpty() }?.let { return it }
      level = level.flatMap { it.children }
    }
    return emptyList()
  }

  private fun AndroidTestTarget.findSemanticsNode(semanticsId: Int): SemanticsNode? {
    fun walk(node: SemanticsNode): SemanticsNode? {
      if (node.id == semanticsId) return node
      node.children.forEach { child -> walk(child)?.let { return it } }
      return null
    }
    composeRoots().forEach { root -> walk(root)?.let { return it } }
    return null
  }

  private fun SemanticsNode.relocationNote(
    capability: String,
    direction: String,
    site: SemanticsNode,
  ) = "Compose node $id is not $capability, so the action ran on its $direction ${site.id}."

  private fun AndroidComposeTestRule<*, *>.nodeWithId(semanticsId: Int): SemanticsNodeInteraction =
    onNode(
      SemanticsMatcher("semantics id is $semanticsId") { it.id == semanticsId },
      useUnmergedTree = true,
    )

  private fun AndroidTestTarget.requireComposeRule() =
    requireNotNull(composeTestRule) {
      "A Compose node was resolved but no AndroidComposeTestRule was supplied. Pass the rule " +
        "already installed by the app's test harness."
    }
}

package xyz.block.trailblaze.api

import kotlin.test.Test
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

class TrailblazeNodeSelectorGeneratorComposeTest : TrailblazeNodeSelectorGeneratorTestBase() {

  // -- Compose Strategy 1: testTag --

  @Test
  fun `Compose - testTag selector`() {
    nextId = 1L
    val target = nodeOf(detail = DriverNodeDetail.Compose(testTag = "submit_btn", text = "Submit"))
    val other = nodeOf(detail = DriverNodeDetail.Compose(testTag = "cancel_btn", text = "Cancel"))
    val root = nodeOf(detail = DriverNodeDetail.Compose(), children = listOf(target, other))

    val selector = assertUniqueMatch(root, target)
    val match = selector.driverMatch as DriverNodeMatch.Compose
    assertNotNull(match.testTag)
  }

  // -- Compose Strategy 2: role + text --

  @Test
  fun `Compose - role plus text selector`() {
    nextId = 1L
    val target = nodeOf(detail = DriverNodeDetail.Compose(role = "Button", text = "Save"))
    val other = nodeOf(detail = DriverNodeDetail.Compose(role = "Button", text = "Delete"))
    val root = nodeOf(detail = DriverNodeDetail.Compose(), children = listOf(target, other))

    val selector = assertUniqueMatch(root, target)
    val match = selector.driverMatch as DriverNodeMatch.Compose
    assertNotNull(match.textRegex)
  }

  // -- Compose Strategy 2: text alone (no role) --

  @Test
  fun `Compose - text alone when unique`() {
    nextId = 1L
    val target = nodeOf(detail = DriverNodeDetail.Compose(text = "Welcome"))
    val other = nodeOf(detail = DriverNodeDetail.Compose(text = "Goodbye"))
    val root = nodeOf(detail = DriverNodeDetail.Compose(), children = listOf(target, other))

    val selector = assertUniqueMatch(root, target)
    val match = selector.driverMatch as DriverNodeMatch.Compose
    assertNotNull(match.textRegex)
  }

  // -- Compose Strategy 8: stateDescription (+ role) --

  /**
   * A custom control whose only identifying property is the state label it publishes. Without a
   * strategy for it, the generator falls through to the hierarchy and index fallbacks, and a
   * reorder of its peers then breaks the recorded selector.
   */
  @Test
  fun `Compose - state description identifies a control with no text or tag`() {
    nextId = 1L
    val target = nodeOf(detail = DriverNodeDetail.Compose(role = "Switch", stateDescription = "Expanded"))
    val other = nodeOf(detail = DriverNodeDetail.Compose(role = "Switch", stateDescription = "Collapsed"))
    val root = nodeOf(detail = DriverNodeDetail.Compose(), children = listOf(target, other))

    val selector = assertUniqueMatch(root, target)
    val match = selector.driverMatch as DriverNodeMatch.Compose
    assertNotNull(match.stateDescriptionRegex)
  }

  /**
   * "3 of 10" / "50%" change between runs, so a selector built on one is a scheduled flake. The
   * generator must skip them and reach for something else — here, the index fallback.
   */
  @Test
  fun `Compose - a numeric state description is not used as an identity`() {
    nextId = 1L
    val target = nodeOf(detail = DriverNodeDetail.Compose(role = "Slider", stateDescription = "3 of 10"))
    val other = nodeOf(detail = DriverNodeDetail.Compose(role = "Slider", stateDescription = "7 of 10"))
    val root = nodeOf(detail = DriverNodeDetail.Compose(), children = listOf(target, other))

    val selector = assertUniqueMatch(root, target)
    val match = selector.driverMatch as DriverNodeMatch.Compose
    assertTrue(
      match.stateDescriptionRegex == null,
      "a run-varying state description must not become the selector: $match",
    )
  }

  // -- Compose Strategy 3: childOf unique parent --

  @Test
  fun `Compose - childOf unique parent`() {
    nextId = 1L
    val target = nodeOf(
      detail = DriverNodeDetail.Compose(text = "OK"),
      bounds = TrailblazeNode.Bounds(10, 110, 100, 150),
    )
    val otherOk = nodeOf(
      detail = DriverNodeDetail.Compose(text = "OK"),
      bounds = TrailblazeNode.Bounds(10, 310, 100, 350),
    )
    val parent = nodeOf(
      detail = DriverNodeDetail.Compose(testTag = "confirm_dialog"),
      bounds = TrailblazeNode.Bounds(0, 100, 200, 200),
      children = listOf(target),
    )
    val otherParent = nodeOf(
      detail = DriverNodeDetail.Compose(testTag = "delete_dialog"),
      bounds = TrailblazeNode.Bounds(0, 300, 200, 400),
      children = listOf(otherOk),
    )
    val root = nodeOf(detail = DriverNodeDetail.Compose(), children = listOf(parent, otherParent))

    val selector = assertUniqueMatch(root, target)
    assertNotNull(selector.childOf, "Expected childOf selector for Compose")
  }

  // -- Compose Strategy 4: spatial below sibling --

  @Test
  fun `Compose - spatial below sibling`() {
    nextId = 1L
    val anchor = nodeOf(
      detail = DriverNodeDetail.Compose(text = "Section Title"),
      bounds = TrailblazeNode.Bounds(0, 100, 400, 150),
    )
    val other = nodeOf(
      detail = DriverNodeDetail.Compose(role = "Image"),
      bounds = TrailblazeNode.Bounds(0, 0, 200, 40),
    )
    val target = nodeOf(
      detail = DriverNodeDetail.Compose(role = "Image"),
      bounds = TrailblazeNode.Bounds(0, 160, 200, 200),
    )
    val root = nodeOf(
      detail = DriverNodeDetail.Compose(),
      children = listOf(other, anchor, target),
      bounds = TrailblazeNode.Bounds(0, 0, 400, 200),
    )

    val selector = assertUniqueMatch(root, target)
    assertTrue(
      selector.below != null || selector.above != null ||
        selector.leftOf != null || selector.rightOf != null,
      "Expected spatial relationship in Compose selector",
    )
  }
}

package xyz.block.trailblaze.api

import kotlin.test.Test
import kotlin.test.assertContains

import kotlin.test.assertTrue

/**
 * The compact hierarchy is what a Compose selector gets authored from. A property the collector
 * captures and this rendering drops is a property no trail can be written against, however well
 * the resolver supports it — so every field on [DriverNodeDetail.Compose] that has a slot here has
 * to reach it.
 */
class AndroidCompactElementListComposeStateTest {

  private var nextId = 0L

  private fun node(
    detail: DriverNodeDetail.Compose,
    children: List<TrailblazeNode> = emptyList(),
  ): TrailblazeNode = TrailblazeNode(
    nodeId = nextId++,
    driverDetail = detail,
    bounds = TrailblazeNode.Bounds(0, 0, 100, 50),
    children = children,
  )

  private fun root(vararg children: TrailblazeNode) =
    node(DriverNodeDetail.Compose(testTag = "root"), children = children.toList())

  @Test
  fun `two rows differing only by state description are distinguishable`() {
    // The case the field exists for: same role, same label, same everything a selector could name
    // — except the state each one is in. Rendered without it, the agent has two identical lines and
    // no way to author `stateDescriptionRegex`, which the resolver supports.
    val text = AndroidCompactElementList.build(
      root(
        node(
          DriverNodeDetail.Compose(
            role = "Button",
            text = "Details",
            stateDescription = "Expanded",
            hasClickAction = true,
          ),
        ),
        node(
          DriverNodeDetail.Compose(
            role = "Button",
            text = "Details",
            stateDescription = "Collapsed",
            hasClickAction = true,
          ),
        ),
      ),
    ).text

    assertContains(text, "Expanded")
    assertContains(text, "Collapsed")
  }

  @Test
  fun `a toggle with no state description still reports its toggle state`() {
    // The fallback. `toggleableState` held the state slot outright before, and a checkbox that
    // stopped saying whether it is on would be a regression traded for the fix above.
    val text = AndroidCompactElementList.build(
      root(
        node(
          DriverNodeDetail.Compose(
            role = "Checkbox",
            text = "Remember me",
            toggleableState = "On",
            hasClickAction = true,
          ),
        ),
      ),
    ).text

    assertContains(text, "On")
  }

  @Test
  fun `an app-authored state description wins over the derived toggle label`() {
    val text = AndroidCompactElementList.build(
      root(
        node(
          DriverNodeDetail.Compose(
            role = "Switch",
            text = "Notifications",
            stateDescription = "Muted until tomorrow",
            toggleableState = "Off",
            hasClickAction = true,
          ),
        ),
      ),
    ).text

    assertContains(text, "Muted until tomorrow")
  }

  @Test
  fun `heading, pane title and error reach the agent`() {
    // Three more fields the collector captures and this mapper used to hardcode away. Grouped
    // because they are one defect, not three: a Compose property with a slot here that never
    // reached it.
    val text = AndroidCompactElementList.build(
      root(
        node(DriverNodeDetail.Compose(text = "Payment methods", isHeading = true)),
        node(
          DriverNodeDetail.Compose(
            role = "TextField",
            text = "Card number",
            editableText = "4242",
            errorText = "Card expired",
          ),
        ),
        // No text of its own — the pane title is the only name this container has, which is the
        // case the field exists for (a dialog or bottom sheet).
        node(
          DriverNodeDetail.Compose(paneTitle = "Checkout"),
          children = listOf(DriverNodeDetail.Compose(text = "Total", hasClickAction = true).let(::node)),
        ),
      ),
    ).text

    assertTrue("[heading]" in text, "A Compose heading must render as one:\n$text")
    assertContains(text, "Card expired")
    assertContains(text, "Checkout")
  }

  @Test
  fun `toggle state still renders when a state description takes the state slot`() {
    // The two are independent readings of the same control, and the checked marker is derived from
    // `toggleableState` rather than from the rendered state label — so a control that has both must
    // print both, not trade one for the other.
    val text = AndroidCompactElementList.build(
      root(
        node(
          DriverNodeDetail.Compose(
            role = "Checkbox",
            text = "Remember me",
            stateDescription = "Saved for 30 days",
            toggleableState = "On",
            hasClickAction = true,
          ),
        ),
      ),
    ).text

    val line = text.lines().single { "Remember me" in it }
    assertContains(line, "[checked]")
    assertContains(line, "Saved for 30 days")
  }
}

package xyz.block.trailblaze

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import kotlin.test.AfterTest
import kotlin.test.BeforeTest
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertTrue
import xyz.block.trailblaze.util.Console

/**
 * Pins the log-redaction half of the sensitive-key contract: a value stored under a key marked
 * via [AgentMemory.rememberSensitive] (`--secret`) must never reach the console log in cleartext —
 * including through a plain [AgentMemory.remember] of the already-marked key, and after a
 * [AgentMemory.delete] of it (the marker is sticky for the session).
 *
 * Lives in `jvmTest` (not `jvmAndAndroidTest`) because it captures output through the JVM
 * `Console` actual's cached stream fields, using the same save/restore harness as [ConsoleTest]
 * (`Console` caches `System.out` at class-init time, so `System.setOut` alone can't intercept).
 */
class AgentMemoryLogRedactionTest {

  private lateinit var originalOutField: PrintStream
  private lateinit var originalUserOutField: PrintStream
  private lateinit var captured: ByteArrayOutputStream

  @BeforeTest fun setUp() {
    captured = ByteArrayOutputStream()
    val newStream = PrintStream(captured, /* autoFlush = */ true, Charsets.UTF_8)
    originalOutField = Console::class.java.getDeclaredField("out").apply { isAccessible = true }
      .get(Console) as PrintStream
    originalUserOutField = Console::class.java.getDeclaredField("userOut").apply { isAccessible = true }
      .get(Console) as PrintStream
    Console::class.java.getDeclaredField("out").apply { isAccessible = true }.set(Console, newStream)
    Console::class.java.getDeclaredField("userOut").apply { isAccessible = true }.set(Console, newStream)
    Console.disableQuietMode()
  }

  @AfterTest fun tearDown() {
    Console.disableQuietMode()
    Console::class.java.getDeclaredField("out").apply { isAccessible = true }.set(Console, originalOutField)
    Console::class.java.getDeclaredField("userOut").apply { isAccessible = true }.set(Console, originalUserOutField)
  }

  private fun logOutput(): String = captured.toString(Charsets.UTF_8)

  @Test
  fun `rememberSensitive does not log the value`() {
    val memory = AgentMemory()
    memory.rememberSensitive("pin", "s3cret-1234")
    val log = logOutput()
    assertFalse(log.contains("s3cret-1234"))
    // The write is still logged (the key appears in the line), so absence of the secret can't
    // be satisfied by logging being suppressed entirely. Deliberately does not pin the
    // redaction wording itself.
    assertTrue(log.contains("pin"))
    assertEquals("s3cret-1234", memory.variables["pin"])
  }

  @Test
  fun `remember on a key marked sensitive logs the write without the value`() {
    val memory = AgentMemory()
    memory.rememberSensitive("pin", "s3cret-1234")
    // Isolate the overwrite's log line from the initial mark's, so the redaction assertion
    // below is about the plain-remember path specifically.
    captured.reset()
    memory.remember("pin", "s3cret-5678")
    val log = logOutput()
    assertFalse(log.contains("s3cret-5678"))
    assertTrue(log.contains("pin"))
    assertEquals("s3cret-5678", memory.variables["pin"])
  }

  @Test
  fun `remember after delete of a sensitive key does not log the value`() {
    // The full --secret acceptance sequence: seed-mark, delete, re-remember. The sticky marker
    // means the re-remember stays redacted instead of re-logging the rotated value.
    val memory = AgentMemory()
    memory.seedFrom(
      yamlDefaults = null,
      cliSeeds = emptyMap(),
      cliSensitiveSeeds = mapOf("apiToken" to "s3cret-original"),
    )
    memory.delete("apiToken")
    assertFalse(logOutput().contains("s3cret-original"))
    // Isolate the re-remember's log line: the write is logged (key appears), the value isn't.
    captured.reset()
    memory.remember("apiToken", "s3cret-rotated")
    val log = logOutput()
    assertFalse(log.contains("s3cret-rotated"))
    assertTrue(log.contains("apiToken"))
    assertEquals("s3cret-rotated", memory.variables["apiToken"])
  }

  @Test
  fun `remember on an unmarked key still logs the value`() {
    // Contrast pin: redaction is scoped to marked keys — a blanket-redaction over-fix that
    // stopped logging ordinary remembered values would break this.
    val memory = AgentMemory()
    memory.remember("businessName", "Coffee Corner")
    assertTrue(logOutput().contains("Coffee Corner"))
  }
}

