import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.semantics.SemanticsNode
import assertk.assertThat
import assertk.assertions.contains
import assertk.assertions.doesNotContain
import kotlin.test.assertFailsWith
import kotlinx.datetime.Clock
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import org.junit.Test
import xyz.block.trailblaze.compose.target.ComposeTestTarget
import xyz.block.trailblaze.devices.TrailblazeDeviceId
import xyz.block.trailblaze.devices.TrailblazeDeviceInfo
import xyz.block.trailblaze.devices.TrailblazeDevicePlatform
import xyz.block.trailblaze.devices.TrailblazeDriverType
import xyz.block.trailblaze.exception.TrailblazeException
import xyz.block.trailblaze.logs.client.TrailblazeLogger
import xyz.block.trailblaze.logs.client.TrailblazeSession
import xyz.block.trailblaze.logs.client.TrailblazeSessionProvider
import xyz.block.trailblaze.logs.client.temp.OtherTrailblazeTool
import xyz.block.trailblaze.logs.model.SessionId
import xyz.block.trailblaze.toolcalls.TrailblazeTool
import xyz.block.trailblaze.utils.NoOpElementComparator

/**
 * Pins that the agent's unhandled-tool error names the TOOL the trail called.
 *
 * Every tool the runtime can't resolve reaches dispatch wrapped as a single
 * [OtherTrailblazeTool], so an error built from the class alone reads identically for all of
 * them and a failed run can't say which tool needs registering.
 */
class ComposeTrailblazeAgentUnhandledToolTest {

  @Test
  fun `unhandled tool error names the wrapped tool, not the wrapper class`() {
    val unresolvable = OtherTrailblazeTool(
      toolName = "checkout_openTipScreen",
      raw = buildJsonObject { put("ref", "z639") },
    )

    val message = dispatchAndCaptureFailure(unresolvable)

    // Anchored to the naming position, not a bare `contains`. `OtherTrailblazeTool` is a data
    // class, so its `toString` — printed further down the message — already carries
    // `toolName=checkout_openTipScreen`. An unanchored match would pass against the very bug
    // this pins: a message whose subject is the wrapper class.
    assertThat(message).contains("Unhandled Trailblaze tool checkout_openTipScreen")
    assertThat(message).contains("arrived unresolved as OtherTrailblazeTool")
  }

  /**
   * The other side of the branch: a tool the agent can't dispatch that did NOT arrive wrapped.
   * It has a real class name to report, and the wrapper explanation would be a lie — so the
   * message must name the class and omit the clause.
   */
  @Test
  fun `unhandled tool error names the class and omits the wrapper clause when not wrapped`() {
    val message = dispatchAndCaptureFailure(UnsupportedShapeTool)

    assertThat(message).contains("Unhandled Trailblaze tool UnsupportedShapeTool")
    assertThat(message).doesNotContain("arrived unresolved as OtherTrailblazeTool")
  }

  /** Dispatches [tool] through the public entry point and returns the failure message. */
  private fun dispatchAndCaptureFailure(tool: TrailblazeTool): String {
    val agent = ComposeTrailblazeAgent(
      target = NoOpComposeTestTarget,
      trailblazeLogger = TrailblazeLogger.createNoOp(),
      trailblazeDeviceInfoProvider = { DEVICE_INFO },
      sessionProvider = TrailblazeSessionProvider {
        TrailblazeSession(
          sessionId = SessionId("unhandled-tool-test"),
          startTime = Clock.System.now(),
        )
      },
      // No repo, so a wrapper survives resolution and reaches the unsupported-tool branch —
      // exactly what a trail calling a tool nobody registered does at runtime.
      trailblazeToolRepo = null,
    )

    val exception = assertFailsWith<TrailblazeException> {
      agent.runTrailblazeTools(
        tools = listOf(tool),
        elementComparator = NoOpElementComparator,
      )
    }
    return exception.message.orEmpty()
  }

  /** A tool implementing none of the shapes the Compose agent dispatches. */
  @Serializable
  private object UnsupportedShapeTool : TrailblazeTool

  private companion object {
    val DEVICE_INFO = TrailblazeDeviceInfo(
      trailblazeDeviceId = TrailblazeDeviceId(
        instanceId = "compose-unhandled-tool-test",
        trailblazeDevicePlatform = TrailblazeDevicePlatform.WEB,
      ),
      trailblazeDriverType = TrailblazeDriverType.COMPOSE,
      widthPixels = 100,
      heightPixels = 100,
    )
  }

  /**
   * Stub target: dispatch throws before anything touches the Compose surface, so every member
   * erroring surfaces an accidental call into the target on this path.
   */
  private object NoOpComposeTestTarget : ComposeTestTarget {
    override fun rootSemanticsNode(): SemanticsNode = error("not invoked in failure-path tests")
    override fun allSemanticsNodes(): List<SemanticsNode> = error("not invoked in failure-path tests")
    override fun click(node: SemanticsNode) = error("not invoked in failure-path tests")
    override fun typeText(node: SemanticsNode, text: String) = error("not invoked in failure-path tests")
    override fun clearText(node: SemanticsNode) = error("not invoked in failure-path tests")
    override fun scrollToIndex(node: SemanticsNode, index: Int) = error("not invoked in failure-path tests")
    override fun captureScreenshot(): ImageBitmap? = null
    override fun waitForIdle() = Unit
  }
}

package xyz.block.trailblaze.toolcalls

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertSame
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonArray
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.put
import kotlinx.serialization.json.putJsonArray
import kotlinx.serialization.json.putJsonObject
import xyz.block.trailblaze.logs.client.temp.OtherTrailblazeTool

/**
 * Pins the pure redaction contract behind [SensitiveValuesTrailblazeTool]: every occurrence of a
 * declared value is masked at any depth of the payload, and everything else — including the
 * surrounding elements of the same array — is preserved. This is what lets one token inside a
 * shell argv be masked without blanking the command, which is the whole reason value-based
 * masking exists beside name-based [withSensitiveArgsRedacted].
 */
class SensitiveValuesRedactionTest {

  private val redacted = JsonPrimitive(REDACTED_TOOL_ARG_PLACEHOLDER)

  @Test
  fun masksOneElementOfAnArrayAndKeepsItsNeighbours() {
    val payload = OtherTrailblazeTool(
      toolName = "fixture_tool",
      raw = buildJsonObject {
        putJsonArray("command") { listOf("service", "call", "s16", "tok-abc123").forEach { add(JsonPrimitive(it)) } }
      },
    )

    val out = payload.withSensitiveValuesRedacted(listOf("tok-abc123"))

    assertEquals(
      buildJsonArray { listOf("service", "call", "s16").forEach { add(JsonPrimitive(it)) }; add(redacted) },
      out.raw["command"],
    )
  }

  @Test
  fun masksAtAnyDepthAndInsideLongerStrings() {
    val payload = OtherTrailblazeTool(
      toolName = "fixture_tool",
      raw = buildJsonObject {
        putJsonObject("nested") { put("header", "Bearer tok-abc123") }
        put("plain", "tok-abc123")
      },
    )

    val out = payload.withSensitiveValuesRedacted(listOf("tok-abc123"))

    assertEquals(JsonPrimitive("Bearer <redacted>"), out.raw["nested"]!!.jsonObject["header"])
    assertEquals(redacted, out.raw["plain"])
  }

  @Test
  fun neverTouchesKeysOrNonStringPrimitives() {
    val payload = OtherTrailblazeTool(
      toolName = "fixture_tool",
      raw = buildJsonObject { put("42", 42); put("flag", true) },
    )

    assertSame(payload, payload.withSensitiveValuesRedacted(listOf("42", "true")))
  }

  @Test
  fun returnsTheSameInstanceWhenNothingMatches() {
    val payload = OtherTrailblazeTool(toolName = "fixture_tool", raw = buildJsonObject { put("a", "b") })

    assertSame(payload, payload.withSensitiveValuesRedacted(listOf("zzz")))
    assertSame(payload, payload.withSensitiveValuesRedacted(emptyList()))
    // Blank values are ignored rather than shredding every string into placeholders.
    assertSame(payload, payload.withSensitiveValuesRedacted(listOf("", "  ")))
  }

  @Test
  fun longestValueWinsWhenOneSecretContainsAnother() {
    // Folding shortest-first would destroy the longer value's only literal occurrence and leave
    // `sess-<redacted>-abcd` in the log.
    assertEquals("v=<redacted>", redactSensitiveValuesIn("v=sess-1234-abcd", listOf("1234", "sess-1234-abcd")))
  }

  @Test
  fun replacesEveryOccurrence() {
    assertEquals("<redacted> <redacted>", redactSensitiveValuesIn("tok tok", listOf("tok")))
  }
}

package xyz.block.trailblaze.toolcalls

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertSame
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put
import xyz.block.trailblaze.logs.client.temp.OtherTrailblazeTool

/**
 * Pins the pure redaction contract behind [SensitiveArgsTrailblazeTool]: a payload's named
 * top-level keys are replaced with [REDACTED_TOOL_ARG_PLACEHOLDER] while everything else is
 * preserved byte-for-byte. The log-encode boundary (`toLogPayload()` and the
 * `TrailblazeToolLog` construction sites in `trailblaze-common`) builds on exactly this
 * function, so masking correctness is provable here without any logger wiring.
 */
class SensitiveArgsRedactionTest {

  private fun payload(vararg entries: Pair<String, String>): OtherTrailblazeTool = OtherTrailblazeTool(
    toolName = "fixture_tool",
    raw = buildJsonObject { entries.forEach { (k, v) -> put(k, v) } },
  )

  @Test
  fun masksOnlyTheNamedKeysAndPreservesTheRest() {
    val redacted = payload("password" to "hunter2", "email" to "qa@example.com")
      .withSensitiveArgsRedacted(setOf("password"))

    assertEquals(JsonPrimitive(REDACTED_TOOL_ARG_PLACEHOLDER), redacted.raw["password"])
    assertEquals(JsonPrimitive("qa@example.com"), redacted.raw["email"])
    assertEquals("fixture_tool", redacted.toolName)
  }

  @Test
  fun masksEveryNamedKeyThatIsPresent() {
    val redacted = payload("password" to "hunter2", "token" to "tok-123", "path" to "/tmp/x")
      .withSensitiveArgsRedacted(setOf("password", "token"))

    assertEquals(JsonPrimitive(REDACTED_TOOL_ARG_PLACEHOLDER), redacted.raw["password"])
    assertEquals(JsonPrimitive(REDACTED_TOOL_ARG_PLACEHOLDER), redacted.raw["token"])
    assertEquals(JsonPrimitive("/tmp/x"), redacted.raw["path"])
  }

  @Test
  fun absentKeysAreIgnoredAndTheSameInstanceIsReturned() {
    val original = payload("email" to "qa@example.com")
    assertSame(original, original.withSensitiveArgsRedacted(setOf("password")))
  }

  @Test
  fun emptyKeySetReturnsTheSameInstance() {
    val original = payload("password" to "hunter2")
    assertSame(original, original.withSensitiveArgsRedacted(emptySet()))
  }

  @Test
  fun emptyPayloadIsUntouched() {
    val original = OtherTrailblazeTool(toolName = "fixture_tool", raw = JsonObject(emptyMap()))
    assertSame(original, original.withSensitiveArgsRedacted(setOf("password")))
  }
}

package xyz.block.trailblaze.recording

import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import xyz.block.trailblaze.api.DriverNodeDetail
import xyz.block.trailblaze.api.TrailblazeNode
import xyz.block.trailblaze.api.ViewHierarchyTreeNode
import xyz.block.trailblaze.toolcalls.TrailblazeTool
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull
import kotlin.test.assertSame
import kotlin.test.assertTrue

class InteractionEventBufferTest {

  private val testScope = CoroutineScope(Dispatchers.Default + SupervisorJob())

  @Test
  fun `onTap emits immediately`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onTap(null, 100, 200, null, null)

    assertEquals(1, emissions.size)
    assertEquals("tap", emissions[0].toolName)
  }

  @Test
  fun `onLongPress emits immediately`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onLongPress(null, 100, 200, null, null)

    assertEquals(1, emissions.size)
    assertEquals("longPress", emissions[0].toolName)
  }

  @Test
  fun `onSwipe emits immediately`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onSwipe(100, 200, 100, 500, null, null)

    assertEquals(1, emissions.size)
    assertEquals("swipe", emissions[0].toolName)
  }

  @Test
  fun `special key flushes pending text first`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onCharacterTyped('a', null, null)
    buffer.onCharacterTyped('b', null, null)
    buffer.onSpecialKey("Enter", null, null)

    // Should have flushed text first, then emitted Enter
    assertEquals(2, emissions.size)
    assertEquals("inputText", emissions[0].toolName)
    assertEquals("pressKey", emissions[1].toolName)
  }

  @Test
  fun `tap flushes pending text first`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onCharacterTyped('x', null, null)
    buffer.onTap(null, 100, 200, null, null)

    assertEquals(2, emissions.size)
    assertEquals("inputText", emissions[0].toolName)
    assertEquals("tap", emissions[1].toolName)
  }

  @Test
  fun `flush emits pending text`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onCharacterTyped('t', null, null)
    buffer.onCharacterTyped('e', null, null)
    buffer.onCharacterTyped('s', null, null)
    buffer.onCharacterTyped('t', null, null)

    // Before flush, text is pending (debounce hasn't fired yet)
    buffer.flush()
    assertEquals(1, emissions.size)
    assertEquals("inputText", emissions[0].toolName)
  }

  @Test
  fun `flush with empty buffer does nothing`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.flush()
    assertTrue(emissions.isEmpty())
  }

  @Test
  fun `backspace removes character from buffer before flush`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onCharacterTyped('a', null, null)
    buffer.onCharacterTyped('b', null, null)
    buffer.onCharacterTyped('c', null, null)
    buffer.onBackspace() // remove 'c'
    buffer.flush()

    assertEquals(1, emissions.size)
    assertEquals("inputText", emissions[0].toolName)
  }

  @Test
  fun `backspace on empty buffer does not crash`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onBackspace()
    buffer.flush()
    assertTrue(emissions.isEmpty())
  }

  /**
   * Pins the load-bearing ordering invariant for [InteractionEventBuffer.recordCustomTool]:
   * any pending text in the debounce buffer is flushed BEFORE the custom tool emits. The
   * canonical scenario is "user types into a URL bar, then clicks Back" — without the
   * flush, the user's text would either land in the recording AFTER the navigation or be
   * lost entirely (debounce job racing with subsequent action emission).
   */
  @Test
  fun `recordCustomTool flushes pending text first`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onCharacterTyped('a', null, null)
    buffer.onCharacterTyped('b', null, null)
    buffer.recordCustomTool(tool = TestTool("custom"), toolName = "customTool")

    assertEquals(2, emissions.size)
    assertEquals("inputText", emissions[0].toolName)
    assertEquals("customTool", emissions[1].toolName)
  }

  /**
   * The picker UI re-runs `findAllValidSelectors` / `resolveFromTap` on demand against the
   * captured tree — particularly for `tapOnPoint` cards where the original cascade bailed.
   * That only works if the tree and tap point survive emission. Pin them here.
   */
  @Test
  fun `onTap forwards capturedTree and tapPoint to the emitted interaction`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)
    val tree = TrailblazeNode(
      nodeId = 0L,
      driverDetail = DriverNodeDetail.AndroidMaestro(text = "root"),
    )

    buffer.onTap(node = null, x = 100, y = 200, screenshot = null, hierarchyText = null, trailblazeNodeTree = tree)

    assertEquals(1, emissions.size)
    assertSame(tree, emissions[0].capturedTree)
    assertEquals(100 to 200, emissions[0].tapPoint)
  }

  @Test
  fun `onLongPress forwards capturedTree and tapPoint to the emitted interaction`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)
    val tree = TrailblazeNode(
      nodeId = 0L,
      driverDetail = DriverNodeDetail.AndroidMaestro(text = "root"),
    )

    buffer.onLongPress(node = null, x = 7, y = 9, screenshot = null, hierarchyText = null, trailblazeNodeTree = tree)

    assertEquals(1, emissions.size)
    assertSame(tree, emissions[0].capturedTree)
    assertEquals(7 to 9, emissions[0].tapPoint)
  }

  @Test
  fun `onTap omits capturedTree when not provided`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onTap(node = null, x = 1, y = 2, screenshot = null, hierarchyText = null)

    assertEquals(1, emissions.size)
    assertNull(emissions[0].capturedTree)
    // tapPoint is still populated — it's the user's coordinate, independent of whether the
    // device was able to produce a hierarchy.
    assertEquals(1 to 2, emissions[0].tapPoint)
  }

  @Test
  fun `onSwipe leaves tapPoint and capturedTree null`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.onSwipe(0, 0, 100, 100, null, null)

    assertEquals(1, emissions.size)
    assertNull(emissions[0].capturedTree)
    assertNull(emissions[0].tapPoint)
  }

  @Test
  fun `recordCustomTool with empty text buffer emits only the custom tool`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val buffer = createBuffer(emissions)

    buffer.recordCustomTool(tool = TestTool("custom"), toolName = "customTool")

    assertEquals(1, emissions.size)
    assertEquals("customTool", emissions[0].toolName)
  }

  /**
   * The auto-advancing-field scenario: an OTP box moves focus to the next box while the
   * burst is still buffering. The recorded tool must name the field the text went INTO, so
   * the buffer has to snapshot the target when the burst opens rather than let the factory
   * resolve one at flush.
   */
  @Test
  fun `text is recorded against the field focused when the burst started`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val factory = TestToolFactory()
    factory.focusedField = "otp-box-1"
    val buffer = InteractionEventBuffer(
      scope = testScope,
      textDebounceMs = 500L,
      toolFactory = factory,
      onInteraction = { emissions.add(it) },
    )

    buffer.onCharacterTyped('4', null, null)
    // The field's own input handler advances focus before the debounce elapses.
    factory.focusedField = "otp-box-2"
    buffer.onCharacterTyped('2', null, null)
    buffer.flush()

    assertEquals(1, emissions.size)
    assertEquals(
      "inputText(42)@otp-box-1",
      (emissions[0].tool as TestTool).description,
      "The burst belongs to the field it started in, not the one focus moved to.",
    )
  }

  /** Text arriving as one complete string has no burst to snapshot, so live focus wins. */
  @Test
  fun `submitted text resolves the target at emit time`() {
    val emissions = mutableListOf<RecordedInteraction>()
    val factory = TestToolFactory()
    factory.focusedField = "search-box"
    val buffer = InteractionEventBuffer(
      scope = testScope,
      textDebounceMs = 500L,
      toolFactory = factory,
      onInteraction = { emissions.add(it) },
    )

    buffer.onTextSubmitted("hello", null, null)

    assertEquals("inputText(hello)@search-box", (emissions[0].tool as TestTool).description)
  }

  private fun createBuffer(
    emissions: MutableList<RecordedInteraction>,
  ): InteractionEventBuffer {
    return InteractionEventBuffer(
      scope = testScope,
      textDebounceMs = 500L,
      toolFactory = TestToolFactory(),
      onInteraction = { emissions.add(it) },
    )
  }
}

/** Stands in for a platform's focus snapshot; [TestToolFactory] moves it between calls. */
private class TestInputTarget(val field: String?) : InputTarget

private class TestToolFactory : InteractionToolFactory {
  /** Mutable so a test can move focus mid-burst, the way an auto-advancing field does. */
  var focusedField: String? = null

  override fun captureInputTarget(): InputTarget = TestInputTarget(focusedField)

  override fun createTapTool(
    node: ViewHierarchyTreeNode?,
    x: Int,
    y: Int,
    trailblazeNodeTree: TrailblazeNode?,
  ): Pair<TrailblazeTool, String> = TestTool("tap($x,$y)") to "tap"

  override fun createLongPressTool(
    node: ViewHierarchyTreeNode?,
    x: Int,
    y: Int,
    trailblazeNodeTree: TrailblazeNode?,
  ): Pair<TrailblazeTool, String> = TestTool("longPress($x,$y)") to "longPress"

  override fun createSwipeTool(
    startX: Int,
    startY: Int,
    endX: Int,
    endY: Int,
    durationMs: Long?,
  ): Pair<TrailblazeTool, String> = TestTool("swipe($startX,$startY,$endX,$endY)") to "swipe"

  override fun createInputTextTool(text: String, target: InputTarget?): Pair<TrailblazeTool, String> {
    val field = (target as? TestInputTarget)?.field ?: focusedField
    return TestTool("inputText($text)@$field") to "inputText"
  }

  override fun createPressKeyTool(key: String): Pair<TrailblazeTool, String> =
    TestTool("pressKey($key)") to "pressKey"
}

private data class TestTool(val description: String) : TrailblazeTool

package xyz.block.trailblaze.model

import kotlin.reflect.KClass
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertNull
import kotlin.test.assertTrue
import xyz.block.trailblaze.devices.TrailblazeDevicePlatform
import xyz.block.trailblaze.devices.TrailblazeDriverType
import xyz.block.trailblaze.toolcalls.TrailblazeTool

/**
 * Pins [TrailblazeHostAppTarget.getAppIdIfInstalled]'s priority-order semantics — the contract
 * downstream callers depend on:
 *
 * - `MobileDeviceUtils.findInstalledAppIdForTarget` (host-side iOS / generic flow)
 * - downstream `AndroidTrailblazeRule` subclass paths
 * - `DeviceSelectionDialog` previews
 *
 * The function must iterate the **target's** declared list in YAML/declaration order — *not*
 * the device's installed-apps listing — so that when multiple declared ids are installed on
 * the same device the first-declared (most-preferred) wins. Concrete failure mode the absence
 * of this test let through previously: when two declared Android variants of the same app
 * were both installed on the same CI agent (e.g. the production package alongside the dev
 * package), a parallel implementation iterated the device listing as the outer loop. That
 * listing is sourced from `PackageManager.getInstalledApplications(0)`, whose iteration order
 * is unspecified by the platform — so the rule effectively picked whichever id PM happened to
 * surface first rather than the target's declared priority. Downstream tests deterministically
 * failed because the wrong package opened. The Android rule has since been refactored to
 * delegate to this canonical resolver — pinning the canonical behavior here means a future
 * regression to either path fails this test.
 */
class TrailblazeHostAppTargetGetAppIdIfInstalledTest {

  private object MultiVariantTarget :
    TrailblazeHostAppTarget(id = "multi-variant", displayName = "Multi-Variant") {
    // A target declaring three Android variants: dev variant first (preferred for CI),
    // engineering variant second, production third. Order is load-bearing here.
    override fun getPossibleAppIdsForPlatform(platform: TrailblazeDevicePlatform): List<String>? =
      when (platform) {
        TrailblazeDevicePlatform.ANDROID -> listOf(
          "com.example.app.dev",
          "com.example.app.eng",
          "com.example.app",
        )
        else -> null
      }

    override fun internalGetCustomToolsForDriver(
      driverType: TrailblazeDriverType,
    ): Set<KClass<out TrailblazeTool>> = emptySet()
  }

  @Test
  fun `picks first-declared appId when multiple are installed (priority over installed-set order)`() {
    // Both `com.example.app` and `com.example.app.dev` are installed. The function must
    // return the first-DECLARED one (dev), NOT whichever id happens to come up
    // first when iterating the installed set. The exact order of the installed set is
    // determined by the platform (Android `PackageManager.getInstalledApplications(0)`
    // doesn't guarantee any particular order), so the picking logic must not depend on it.
    // This is the regression case the bug surfaced.
    val installed = setOf(
      "com.android.chrome",
      "com.example.app",
      "com.example.app.dev",
      "com.example.unrelated",
    )
    assertEquals(
      "com.example.app.dev",
      MultiVariantTarget.getAppIdIfInstalled(TrailblazeDevicePlatform.ANDROID, installed),
    )
  }

  @Test
  fun `falls through declared list to a later entry when earlier ones are not installed`() {
    // Only `com.example.app.eng` (the second-declared) is installed. The first-declared
    // `com.example.app.dev` isn't on the device, and the third `com.example.app` isn't
    // either — so the resolver walks past missing entries and returns the eng variant.
    val installed = setOf("com.example.app.eng", "com.android.chrome")
    assertEquals(
      "com.example.app.eng",
      MultiVariantTarget.getAppIdIfInstalled(TrailblazeDevicePlatform.ANDROID, installed),
    )
  }

  @Test
  fun `returns null when no declared appId is installed`() {
    // None of the target's declared ids are on the device. Caller is expected to handle
    // null (typically by erroring with a "please install one of …" message).
    val installed = setOf("com.android.chrome", "com.example.unrelated")
    assertNull(MultiVariantTarget.getAppIdIfInstalled(TrailblazeDevicePlatform.ANDROID, installed))
  }

  @Test
  fun `returns null when the platform has no declared appIds`() {
    // MultiVariantTarget declares Android only. iOS lookup returns null regardless of what's
    // "installed" in the test set — there's no declared list to intersect with.
    val installed = setOf("com.example.app.dev")
    assertNull(MultiVariantTarget.getAppIdIfInstalled(TrailblazeDevicePlatform.IOS, installed))
  }

  // --- requireInstalledAppIdForDevice (throwing variant) ---
  //
  // Pins the throw-with-fallback behavior the host (`MobileDeviceUtils.findInstalledAppIdForTarget`)
  // and downstream on-device Android rule paths both delegate to. The priority semantics
  // (first declared wins) are covered by the soft-fail tests above; these focus on the wrapper
  // behavior.

  private object AllowsNotInstalledTarget :
    TrailblazeHostAppTarget(id = "stand-in", displayName = "Stand-In") {
    override fun getPossibleAppIdsForPlatform(platform: TrailblazeDevicePlatform): List<String>? =
      when (platform) {
        TrailblazeDevicePlatform.ANDROID -> listOf("com.example.standin.primary", "com.example.standin.alt")
        else -> null
      }

    override val allowsAppNotInstalled: Boolean = true

    override fun internalGetCustomToolsForDriver(
      driverType: TrailblazeDriverType,
    ): Set<KClass<out TrailblazeTool>> = emptySet()
  }

  @Test
  fun `requireInstalledAppIdForDevice returns first declared match`() {
    // First-declared `com.example.app.dev` is installed alongside the third-declared
    // `com.example.app`. The throwing variant has to honor the same priority order the
    // soft-fail variant does — declaration order, not installed-set order.
    val installed = setOf("com.example.app", "com.example.app.dev")
    assertEquals(
      "com.example.app.dev",
      MultiVariantTarget.requireInstalledAppIdForDevice(TrailblazeDevicePlatform.ANDROID, installed),
    )
  }

  @Test
  fun `requireInstalledAppIdForDevice throws when no declared appId is installed`() {
    // None of the target's declared ids are on the device. The throwing variant fails fast
    // with a diagnostic message rather than letting the caller proceed with a null id and
    // bubble a less actionable failure further down the launch chain.
    val installed = setOf("com.android.chrome", "com.example.unrelated")
    val ex = assertFailsWith<IllegalStateException> {
      MultiVariantTarget.requireInstalledAppIdForDevice(TrailblazeDevicePlatform.ANDROID, installed)
    }
    // Diagnostic message must name the target id, the declared ids, and the installed set —
    // the three pieces an oncaller needs to act (install one of the declared ids, or update
    // the target's declared list to include the installed id).
    val msg = ex.message ?: ""
    assertTrue("missing target id in $msg") { "multi-variant" in msg }
    assertTrue("missing declared ids in $msg") { "com.example.app.dev" in msg }
    assertTrue("missing installed set in $msg") { "com.android.chrome" in msg }
  }

  @Test
  fun `requireInstalledAppIdForDevice throws when platform has no declared appIds`() {
    // MultiVariantTarget declares Android only — iOS request has no list to intersect, so
    // even an "installed" set with the right id fails with a "no app ids configured"
    // message. The throwing variant distinguishes this from the no-install-match case so
    // operators don't waste time chasing a missing install when the real issue is a
    // missing declaration.
    val installed = setOf("com.example.app.dev")
    assertFailsWith<IllegalStateException> {
      MultiVariantTarget.requireInstalledAppIdForDevice(TrailblazeDevicePlatform.IOS, installed)
    }
  }

  // --- DefaultTrailblazeHostAppTarget singleton ---
  //
  // Pins the contract of the built-in stand-in target — every platform must report as
  // supported (empty list, not null) and `allowsAppNotInstalled` must be true. Without
  // these, the Run Configuration dialog's `acceptsDeviceForPlatform` gate disables every
  // device row when discovery falls back to the singleton (clean checkout with no
  // `default.yaml`). PR #3118 follow-up.

  @Test
  fun `DefaultTrailblazeHostAppTarget allows app not installed`() {
    assertTrue(TrailblazeHostAppTarget.DefaultTrailblazeHostAppTarget.allowsAppNotInstalled)
  }

  @Test
  fun `DefaultTrailblazeHostAppTarget reports every platform as supported with no specific id`() {
    val default = TrailblazeHostAppTarget.DefaultTrailblazeHostAppTarget
    for (platform in TrailblazeDevicePlatform.entries) {
      assertEquals(
        emptyList(),
        default.getPossibleAppIdsForPlatform(platform),
        "DefaultTrailblazeHostAppTarget must return emptyList (not null) for $platform — " +
          "null would be misread as 'platform not supported' by acceptsDeviceForPlatform.",
      )
    }
  }

  @Test
  fun `DefaultTrailblazeHostAppTarget accepts any device with no installed app`() {
    val default = TrailblazeHostAppTarget.DefaultTrailblazeHostAppTarget
    for (platform in TrailblazeDevicePlatform.entries) {
      assertTrue(default.acceptsDeviceForPlatform(platform, installedAppId = null))
    }
  }

  @Test
  fun `requireInstalledAppIdForDevice falls back to first declared when allowsAppNotInstalled`() {
    // Stand-in targets (e.g. the generic `default` target) opt in via [allowsAppNotInstalled]
    // because their declared id is a placeholder, not a real product package — the absence
    // of any installed match is expected, not a failure. Fallback uses the first declared id
    // so it aligns with the priority semantics of the non-fallback path. Real product
    // targets stay strict (covered by the throw-test above) so a missing install fails fast
    // at rule construction with a clear "please install" error rather than later when
    // something tries to launch the missing package.
    val installed = setOf("com.example.unrelated")
    assertEquals(
      "com.example.standin.primary",
      AllowsNotInstalledTarget.requireInstalledAppIdForDevice(TrailblazeDevicePlatform.ANDROID, installed),
    )
  }
}

