  // ---------------------------------------------------------------------------
  // mapToTrailblazeTool — no-repo fallback (regression for #2634 lead-dev review)
  // ---------------------------------------------------------------------------

  @Test
  fun `mapToTrailblazeTool wraps as OtherTrailblazeTool when no repo configured`() {
    // Pins the no-repo fallback path. With neither `dynamicToolRepoProvider` nor
    // `trailblazeToolRepo` wired, the executor must wrap the args verbatim so the bridge
    // can still forward to the device — without this, a callsite that legitimately doesn't
    // need a repo would hard-fail on every tool dispatch.
    val executorWithoutRepo = BridgeUiActionExecutor(mcpBridge = ConfigurableMockBridge())
    val args = buildJsonObject { put("ref", "z639") }

    val tool = runBlocking {
      executorWithoutRepo.mapToTrailblazeTool(toolName = "tap", args = args)
    }

    assertTrue(tool is OtherTrailblazeTool, "expected OtherTrailblazeTool wrap, got ${tool::class.simpleName}")
    val wrapped = tool as OtherTrailblazeTool
    assertEquals("tap", wrapped.toolName)
    assertEquals(args, wrapped.raw)
  }

  // ---------------------------------------------------------------------------
  // launchApp pre-validation
  // ---------------------------------------------------------------------------

  private fun launchApp(appId: String, configure: ConfigurableMockBridge.() -> Unit): ExecutionResult {
    val bridge = ConfigurableMockBridge().apply(configure)
    return runBlocking {
      BridgeUiActionExecutor(mcpBridge = bridge)
        .execute(toolName = "launchApp", args = buildJsonObject { put("appId", appId) }, traceId = null)
    }
  }

  @Test
  fun `launchApp is rejected when the device reports the app is not installed`() {
    val result = launchApp("com.missing.app") { installedAppIds = setOf("com.example.app") }

    // Non-recoverable and lists what IS installed, so the agent retries with a real id instead
    // of hammering the same wrong one.
    assertTrue(result is ExecutionResult.Failure, "expected rejection, got $result")
    assertFalse((result as ExecutionResult.Failure).recoverable)
    assertTrue(result.error.contains("not installed"), result.error)
    assertTrue(result.error.contains("com.example.app"), result.error)
  }

  @Test
  fun `launchApp proceeds when the installed-app probe fails`() {
    // The permissive path: a probe that couldn't answer must not be read as "zero apps
    // installed", which would reject every launch with a confident and wrong "not installed".
    val result = launchApp("com.example.app") {
      installedAppIdsException = IllegalStateException("device probe failed")
    }

    assertTrue(result is ExecutionResult.Success, "expected the launch to proceed, got $result")
  }

  @Test
  fun `launchApp propagates cancellation instead of reporting a retryable failure`() {
    // A stopped run must unwind. Kotlin's CancellationException is an Exception, so every catch
    // between here and the caller has to let it past — otherwise the agent loop is handed a
    // retryable error and keeps going after the user hit stop.
    assertFailsWith<CancellationException> {
      launchApp("com.example.app") { installedAppIdsException = CancellationException("run stopped") }
    }
  }

  // ---------------------------------------------------------------------------
  // getScreenSummary
  // ---------------------------------------------------------------------------

  /**
   * The summary is text from the element tree — the screen every `trailblaze tool` call prints.
   * Asking for screenshots made the device render, encode and ship two images per call only for
   * them to be discarded.
   */
  @Test
  fun `the screen summary asks the device for no screenshots`() = runBlocking {
    val requests = mutableListOf<String>()
    val bridge = object : TrailblazeMcpBridge by ConfigurableMockBridge() {
      override fun isOnDeviceInstrumentation(): Boolean = true

      override suspend fun getScreenStateViaRpc(
        includeScreenshot: Boolean,
        screenshotScalingConfig: ScreenshotScalingConfig,
        includeAnnotatedScreenshot: Boolean,
        includeAllElements: Boolean,
      ): GetScreenStateResponse? {
        requests += "rpc screenshot=$includeScreenshot annotated=$includeAnnotatedScreenshot"
        return null
      }

      override fun getDirectScreenStateProvider(
        skipScreenshot: Boolean,
      ): ((ScreenshotScalingConfig) -> ScreenState)? {
        requests += "direct skipScreenshot=$skipScreenshot"
        return null
      }
    }

    BridgeUiActionExecutor(mcpBridge = bridge).getScreenSummary()

    assertEquals(listOf("rpc screenshot=false annotated=false", "direct skipScreenshot=true"), requests)
  }
}

package xyz.block.trailblaze.trailrunner

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertNull
import kotlin.test.assertTrue
import kotlinx.coroutines.runBlocking

/**
 * The permission state is the daemon-side truth of which spawned-CLI tool calls a human has decided
 * on. These pin its observable contract - what a resolution hands back to the awaiting caller and
 * which tools become pre-approved - without a live daemon, proxy, or CLI.
 */
class ExternalAgentPermissionsTest {

  @Test
  fun registeringSurfacesThePendingRequestAndAwaitingBlocksUntilResolved() {
    val state = ExternalAgentPermissionState()
    val req = state.register(toolName = "tap", inputJson = """{"x":1}""", toolUseId = "tu-1")

    val snapshot = state.pendingSnapshot()
    assertEquals(1, snapshot.size)
    assertEquals("tap", snapshot.single().toolName)
    assertEquals(req.id, snapshot.single().id)
    assertFalse(req.deferred.isCompleted)
  }

  @Test
  fun allowResolvesWithThePassThroughInputAndClearsThePending() {
    val state = ExternalAgentPermissionState()
    val req = state.register(toolName = "tap", inputJson = """{"x":1}""", toolUseId = null)

    val resolved = state.resolve(req.id, "allow")

    assertEquals(PermissionOutcome.ALLOW, resolved?.outcome)
    val decision = runBlocking { req.deferred.await() }
    assertTrue(decision is PermissionDecision.Allow)
    assertEquals("""{"x":1}""", decision.updatedInputJson)
    assertTrue(state.pendingSnapshot().isEmpty())
  }

  @Test
  fun denyResolvesWithADenyDecision() {
    val state = ExternalAgentPermissionState()
    val req = state.register(toolName = "tap", inputJson = null, toolUseId = null)

    val resolved = state.resolve(req.id, "deny")

    assertEquals(PermissionOutcome.DENY, resolved?.outcome)
    assertTrue(runBlocking { req.deferred.await() } is PermissionDecision.Deny)
  }

  @Test
  fun allowAlwaysPreApprovesThatToolForLaterRequests() {
    val state = ExternalAgentPermissionState()
    assertFalse(state.isPreApproved("tap"))
    val req = state.register(toolName = "tap", inputJson = null, toolUseId = null)

    val resolved = state.resolve(req.id, "allow_always")

    assertEquals(PermissionOutcome.ALLOW_ALWAYS, resolved?.outcome)
    assertTrue(state.isPreApproved("tap"))
    // A different tool is still gated.
    assertFalse(state.isPreApproved("inputText"))
  }

  @Test
  fun resolvingAnUnknownIdReturnsNull() {
    val state = ExternalAgentPermissionState()
    assertNull(state.resolve("perm-missing", "allow"))
  }

  @Test
  fun enablingAutoApprovePreApprovesEverythingAndAllowsWhatWasPending() {
    val state = ExternalAgentPermissionState()
    val req = state.register(toolName = "tap", inputJson = """{"x":1}""", toolUseId = null)

    val drained = state.setAutoApprove(true)

    assertTrue(state.autoApprove)
    assertTrue(state.isPreApproved("anything"))
    assertEquals(1, drained.size)
    assertEquals(PermissionOutcome.AUTO_ALLOW, drained.single().outcome)
    val decision = runBlocking { req.deferred.await() }
    assertEquals("""{"x":1}""", (decision as PermissionDecision.Allow).updatedInputJson)
    assertTrue(state.pendingSnapshot().isEmpty())
  }

  @Test
  fun disablingAutoApproveDrainsNothingAndStopsPreApproving() {
    val state = ExternalAgentPermissionState()
    state.setAutoApprove(true)

    val drained = state.setAutoApprove(false)

    assertTrue(drained.isEmpty())
    assertFalse(state.autoApprove)
    assertFalse(state.isPreApproved("tap"))
  }

  @Test
  fun failAllPendingDeniesEveryOutstandingRequestWithTheGivenMessage() {
    val state = ExternalAgentPermissionState()
    val a = state.register(toolName = "tap", inputJson = null, toolUseId = null)
    val b = state.register(toolName = "inputText", inputJson = null, toolUseId = null)

    val drained = state.failAllPending("the run ended before this was approved")

    assertEquals(2, drained.size)
    assertTrue(drained.all { it.outcome == PermissionOutcome.RUN_ENDED })
    assertTrue(runBlocking { a.deferred.await() } is PermissionDecision.Deny)
    assertTrue(runBlocking { b.deferred.await() } is PermissionDecision.Deny)
    assertTrue(state.pendingSnapshot().isEmpty())
  }

  @Test
  fun pendingSnapshotIsOrderedOldestFirst() {
    val state = ExternalAgentPermissionState()
    val first = state.register(toolName = "tap", inputJson = null, toolUseId = null)
    Thread.sleep(2)
    val second = state.register(toolName = "inputText", inputJson = null, toolUseId = null)

    assertEquals(listOf(first.id, second.id), state.pendingSnapshot().map { it.id })
  }
}
